def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_pressure = 0.0
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0.0)
                prev_bids.append(bid)
                if bid > opp_pressure:
                    opp_pressure = bid

    if budget <= 0:
        return 0.0

    if len(alive_opponents) == 0:
        if hp <= 3 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    supply_ratio = (float(supply) - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    tight_supply = supply <= 17
    very_tight_supply = supply <= 16

    if hp <= 2 or no_water >= 2:
        emergency = max(DAILY_SALARY * 1.05, opp_pressure + 4.0)
        return float(min(budget, emergency))

    if hp <= 4 or no_water >= 1:
        urgent = max(DAILY_SALARY * 0.88, opp_pressure + 2.0)
        if very_tight_supply:
            urgent = max(urgent, DAILY_SALARY * 0.98)
        return float(min(budget, urgent))

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    if tight_supply:
        base = DAILY_SALARY * 0.72
        if highest_prev > 0:
            base = max(base, min(highest_prev + 1.5, DAILY_SALARY * 0.96))
        return float(min(budget, base))

    if highest_prev >= 145:
        bid = DAILY_SALARY * 0.34
    elif highest_prev >= 135:
        bid = DAILY_SALARY * 0.42
    elif highest_prev >= 120:
        bid = DAILY_SALARY * 0.52
    else:
        bid = DAILY_SALARY * (0.48 + 0.10 * (1.0 - supply_ratio))
        if avg_prev > 0:
            bid = max(bid, min(avg_prev * 0.52, DAILY_SALARY * 0.7))

    if day >= 8 and hp >= 7:
        bid *= 0.9

    if budget < DAILY_SALARY * 1.2:
        bid = min(bid, budget * 0.7)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Use only yesterday's immediate trace bids to infer pressure.
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # Estimate how much water is likely needed to stay safe.
    # If we already have consecutive no-water days, increase urgency.
    urgency = 0
    if no_water_days >= 2:
        urgency = 2
    elif no_water_days == 1:
        urgency = 1

    # Determine opponent pressure from yesterday.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Base target bid: if opponents were bidding high, we must match/just exceed.
    # Otherwise, bid enough to secure water without burning budget.
    # Keep indices safe (no arrays used), but still ensure numeric safety.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # High pressure day.
        if hp <= 2:
            target = highest_prev_bid + 5.0
        elif hp <= 4:
            target = highest_prev_bid + 2.5
        else:
            target = highest_prev_bid + 1.0
    else:
        # Moderate pressure.
        if hp <= 2:
            target = max(highest_prev_bid + 3.0, DAILY_SALARY * 0.85)
        elif hp <= 4:
            target = max(highest_prev_bid + 2.0, DAILY_SALARY * 0.65)
        else:
            target = max(highest_prev_bid + 1.0, DAILY_SALARY * 0.55)

    # Adjust by our urgency and today's supply (more supply => less need to overbid).
    # supply between 15 and 25, map to discount factor.
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        supply_ratio = 0.0 if supply_ratio < 0.0 else (1.0 if supply_ratio > 1.0 else supply_ratio)
    else:
        supply_ratio = 0.5

    # If supply is high, reduce; if low, increase.
    target *= (1.0 + (0.5 - supply_ratio) * 0.25)

    # Urgency pushes bid up.
    target *= (1.0 + 0.08 * urgency)

    # Budget safety: never bid more than we can afford; also avoid bidding beyond a fraction unless critical.
    critical = (hp <= 2) or (no_water_days >= 2)
    max_affordable = budget
    if critical:
        cap = max_affordable
    else:
        cap = min(max_affordable, DAILY_SALARY * 1.6)

    bid = min(cap, max(0.0, target))

    # If budget is extremely low, bid what we can.
    if budget <= 1.0:
        return min(1.0, budget)

    # Ensure bid is at least 1 when trying to secure water.
    if bid < 1.0 and critical:
        bid = min(1.0, budget)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.3)

    # Determine opponent aggressiveness from yesterday's bid
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid on HP and supply scarcity
    scarcity_factor = max(0, (WATER_REQ - supply) / WATER_REQ)  # negative if supply > req
    hp_factor = max(0, (WATER_REQ - hp) / WATER_REQ)  # high when hp low
    base_urgency = max(scarcity_factor, hp_factor)

    # Adjust based on highest opponent previous bid
    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        if max_prev_bid > DAILY_SALARY * 0.85:
            # Opponent is aggressive, reduce bid to save budget
            aggression_penalty = 0.3
        elif max_prev_bid > DAILY_SALARY * 0.6:
            aggression_penalty = 0.5
        else:
            aggression_penalty = 0.7
    else:
        aggression_penalty = 0.6

    # Desired bid as fraction of salary based on urgency
    if base_urgency > 0.6:
        desired_fraction = 0.9
    elif base_urgency > 0.3:
        desired_fraction = 0.7
    else:
        desired_fraction = 0.5

    # Combine with aggression penalty
    bid = DAILY_SALARY * desired_fraction * aggression_penalty

    # Ensure we don't exceed budget
    bid = min(bid, budget)
    # Ensure minimum bid if we need water badly and have budget
    if no_water_days >= 2 or hp <= 2:
        bid = max(bid, DAILY_SALARY * 0.6)

    return min(bid, budget)
